-- Editable ticket templates + knowledge documents, persisted in Neon.
-- Idempotent: safe to re-run. The seed (the original in-code templates/docs) only runs while a
-- table is completely empty, so edits and deletions made in the app are never overwritten.

create table if not exists iris.ticket_templates (
  code                       text primary key,
  title                      text not null,
  description                text not null default '',
  category                   text not null,
  subcategory                text,
  department_code            text,
  default_priority           text not null default 'P2' check (default_priority in ('P0', 'P1', 'P2', 'P3')),
  default_severity           text,
  suggested_assignee_role    text,
  required_fields            jsonb not null default '[]',
  conditional_fields         jsonb not null default '[]',
  custom_fields              jsonb not null default '[]',
  prefilled_options          jsonb not null default '[]',
  form                       jsonb,                     -- explicit form-builder definition (null = derive from the fields above)
  recommended_actions        text not null default '',
  estimated_resolution_hours integer not null default 24,
  sort_order                 integer not null default 0,
  created_by_user_id         uuid references iris.users(id) on delete set null,
  created_at                 timestamptz not null default now(),
  updated_at                 timestamptz not null default now()
);
create index if not exists idx_ticket_templates_category on iris.ticket_templates(category);

create table if not exists iris.knowledge_docs (
  id                 text primary key,
  title              text not null,
  category           text not null,
  subcategory        text,                               -- Knowledge Base drill-down level 2
  summary            text not null default '',
  steps              jsonb not null default '[]',
  body               text not null default '',          -- markdown
  tags               text[] not null default '{}',
  prevention         text,
  escalation         text,
  related_templates  text[] not null default '{}',
  sort_order         integer not null default 0,
  author_user_id     uuid references iris.users(id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index if not exists idx_knowledge_docs_category on iris.knowledge_docs(category);

drop trigger if exists trg_set_updated_at on iris.ticket_templates;
create trigger trg_set_updated_at before update on iris.ticket_templates
  for each row execute function iris.set_updated_at();
drop trigger if exists trg_set_updated_at on iris.knowledge_docs;
create trigger trg_set_updated_at before update on iris.knowledge_docs
  for each row execute function iris.set_updated_at();

alter table iris.ticket_templates enable row level security;
alter table iris.knowledge_docs enable row level security;
grant select, insert, update, delete on iris.ticket_templates to iris_app;
grant select, insert, update, delete on iris.knowledge_docs to iris_app;

drop policy if exists p_read on iris.ticket_templates;
drop policy if exists p_manager_write on iris.ticket_templates;
create policy p_read on iris.ticket_templates for select to iris_app using (iris.is_signed_in());
create policy p_manager_write on iris.ticket_templates for all to iris_app
  using (iris.is_manager_or_admin()) with check (iris.is_manager_or_admin());

drop policy if exists p_read on iris.knowledge_docs;
drop policy if exists p_manager_write on iris.knowledge_docs;
create policy p_read on iris.knowledge_docs for select to iris_app using (iris.is_signed_in());
create policy p_manager_write on iris.knowledge_docs for all to iris_app
  using (iris.is_manager_or_admin()) with check (iris.is_manager_or_admin());

-- Seed: the original in-code defaults.
do $seed$
begin
  if not exists (select 1 from iris.ticket_templates) then
    insert into iris.ticket_templates (code, title, description, category, subcategory, department_code, default_priority,
