transaction in Momence, compare with displayed credits, apply credit adjustment if verified.","estimated_resolution_hours":6,"sort_order":1},{"code":"TPL-003","title":"Membership Change Request","description":"Client wants to change membership type (upgrade, downgrade, switch).","category":"Membership","subcategory":"Change Request","department_code":"MEM","default_priority":"P3","default_severity":null,"suggested_assignee_role":"Memberships Associate","required_fields":["clientName","currentMembership","desiredMembership"],"conditional_fields":[{"field":"changeType","condition":"Type of change?","options":["Upgrade","Downgrade","Switch plan","Add-on package"]},{"field":"effectiveDate","condition":"When should it take effect?","options":["Immediately","Next billing cycle","Specific date"]}],"custom_fields":[],"prefilled_options":[],"recommended_actions":"Confirm new membership terms, calculate proration, process change in Momence with client confirmation.","estimated_resolution_hours":24,"sort_order":2},{"code":"TPL-004","title":"Membership Cancellation Request","description":"Client requests cancellation of their membership.","category":"Membership","subcategory":"Cancellation","department_code":"MEM","default_priority":"P2","default_severity":null,"suggested_assignee_role":"Memberships Manager","required_fields":["clientName","membershipType","reason"],"conditional_fields":[{"field":"cancellationReason","condition":"Reason for cancellation?","options":["Relocation","Financial","Dissatisfaction","Medical","Other"]},{"field":"effectiveDate","condition":"When to cancel?","options":["Immediate","End of billing cycle","Specific date"]}],"custom_fields":[],"prefilled_options":[],"recommended_actions":"Review cancellation policy, process cancellation in Momence, confirm final billing and access end date.","estimated_resolution_hours":48,"sort_order":3},{"code":"TPL-005","title":"Refund Request — Membership","description":"Client requests refund for membership purchase.",